#!/bin/bash
# Retry schedule for webhook delivery, per ADR-0009.
# Attempts: RELAY_ATTEMPTS (runbook key; RELAY_RETRY_MAX kept as fallback), default 4.
# Wait after attempt i is 3^i seconds (3, 9, 27).
RELAY_ATTEMPTS_DEFAULT=4
RELAY_WAIT_BASE=3
relay_attempts() { echo "${RELAY_ATTEMPTS:-${RELAY_RETRY_MAX:-$RELAY_ATTEMPTS_DEFAULT}}"; }
relay_wait_for() { local i="$1" w=1; while [ "$i" -gt 0 ]; do w=$(( w * RELAY_WAIT_BASE )); i=$(( i - 1 )); done; echo "$w"; }
relay_waits() { local n i=1 out=""; n=$(relay_attempts); while [ "$i" -lt "$n" ]; do out="${out:+$out,}$(relay_wait_for "$i")"; i=$(( i + 1 )); done; echo "$out"; }

